TextExtractor.code_template:
// Create input PDF with known text
var doc = new Aspose.Pdf.Document();
var page = doc.Pages.Add();
page.Paragraphs.Add(new Aspose.Pdf.Text.TextFragment("Hello LowCode PDF"));
doc.Save("input.pdf");

// Extract text
var textOptions = new TextExtractorOptions();
textOptions.AddInput(new FileDataSource("input.pdf"));
var extractor = new TextExtractor();
var result = extractor.Process(textOptions);

// Validate
if (result.IsSuccess)
{
    var text = ((Aspose.Pdf.LowCode.Results.StringResult)result.OperationResult[0]).Data;
    Console.WriteLine(text.Contains("Hello LowCode PDF") ? "TextExtract succeeded" : "Text not found");
}
else Console.WriteLine("TextExtract failed");
